public final class ParityAudit {
 private static void check(String n,boolean ok,Object detail){ServerAudit.check("parity: "+n,ok,detail);}
 private static ItemStack item(String id){return EMTRecipes.stack(id);}
 private static void field(Object object,String name,Object value){try{var f=object.getClass().getDeclaredField(name);f.setAccessible(true);f.set(object,value);}catch(Exception ex){throw new RuntimeException(ex);}}
 private static Object call(Object object,String name){try{var m=object.getClass().getDeclaredMethod(name);m.setAccessible(true);return m.invoke(object);}catch(Exception ex){throw new RuntimeException(ex);}}
 public static void run(ServerLevel l,BlockPos base){var data=EMTRecipes.definitions();check("all79original magic recipes and57researches restored",data.getAsJsonArray("recipes").size()==79&&ResearchCategories.getResearchList("EMT").research.size()==57,"79/57");var missing=new ArrayList<String>();for(var r:ResearchCategories.getResearchList("EMT").research.values()){if(r.parents!=null)for(var key:r.parents)if(ResearchCategories.getResearch(key)==null)missing.add(r.key+"->"+key);if(r.parentsHidden!=null)for(var key:r.parentsHidden)if(ResearchCategories.getResearch(key)==null)missing.add(r.key+"->"+key);}check("every original research prerequisite resolves across addons",missing.isEmpty(),missing);
  var fake=FakePlayerFactory.getMinecraft(l);fake.getInventory().clearContent();fake.setShiftKeyDown(false);fake.removeAllEffects();ResearchProgress.add(fake.getPersistentData(),"UU-Matter Infusion");var matrixPos=base.offset(10,2,58);l.setBlock(matrixPos,InfusionContent.MATRIX.get().defaultBlockState(),3);var matrix=(InfusionContent.MatrixEntity)l.getBlockEntity(matrixPos);int recipes=0,multiple=0;for(var recipe:TC4Addons.infusionRecipes())if(recipe.research().equals("UU-Matter Infusion")){recipes++;var expected=data.getAsJsonArray("recipes").asList().stream().map(e->e.getAsJsonObject()).filter(d->d.get("key").getAsString().equals(recipe.key())).findFirst().orElseThrow().getAsJsonObject("result");int count=expected.get("count").getAsInt();if(count>1)multiple++;var centre=new ItemStack(recipe.central().get());var match=InfusionItemRecipes.match(recipe.componentStacks(),centre,Set.of("UU-Matter Infusion"));var actual=matrix.findRecipe(recipe.componentStacks(),centre,fake);check(recipe.key()+" actual infusion chooses exact output count",match==recipe&&actual!=null&&actual.output().getCount()==count&&actual.output().is(EMTRecipes.item(expected.get("id").getAsString())),actual==null?"missing":actual.output());check(recipe.key()+" missing UU component cannot craft",InfusionItemRecipes.match(recipe.componentStacks().subList(1,recipe.componentStacks().size()),centre,Set.of("UU-Matter Infusion"))==null,"payment");}check("all14UU infusions include twelve multi-item outputs",recipes==14&&multiple==12,recipes+"/"+multiple);l.setBlock(matrixPos,Blocks.AIR.defaultBlockState(),3);
  for(var pair:new String[][]{{"earth","resin"},{"fire","redstone"},{"water","lapis"}}){var key="emt:shardTo"+switch(pair[1]){case "resin"->"Resin";case "redstone"->"Redstone";default->"Lapis";};var recipe=TC4Addons.infusionRecipes().stream().filter(r->r.key().equals(key)).findFirst().orElseThrow();check("formerly ambiguous "+pair[1]+" is reachable with "+pair[0]+" shard",InfusionItemRecipes.match(recipe.componentStacks(),item("tc4modern:"+pair[0]+"_shard"),Set.of("UU-Matter Infusion"))==recipe,key);}
  var crystal=TC4Addons.crucibleRecipes().get("emt:uuMCrystal");var matched=thaumcraft.api.crafting.CrucibleRecipe.findMatching(new ArrayList<>(TC4Addons.crucibleRecipes().values()),Set.of("UU-Matter Infusion"),crystal.aspects.copy(),item("ic2:uu_matter_cell"));check("real UU fluid cell is required by native crucible recipe",matched==crystal&&matched.getRecipeOutput().is(EMTItems.material("uu_matter_drop"))&&thaumcraft.api.crafting.CrucibleRecipe.findMatching(new ArrayList<>(TC4Addons.crucibleRecipes().values()),Set.of("UU-Matter Infusion"),crystal.aspects.copy(),item("ic2:empty_cell"))==null,"UU cell");
  var bench=base.offset(16,0,58);l.setBlock(bench,TC4Modern.ARCANE_WORKBENCH.get().defaultBlockState(),3);fake.setPos(bench.getX()+.5,bench.getY()+1,bench.getZ()+.5);var table=new SimpleContainer(10);var wand=item("tc4modern:wand");for(var a:Aspect.getPrimalAspects())WandData.add(wand,a,25,true);table.setItem(9,wand);table.setItem(4,item("ic2:uranium_238"));var menu=new ArcaneWorkbenchMenu(807,fake.getInventory(),net.minecraft.world.inventory.ContainerLevelAccess.create(l,bench),table);check("tiny uranium recipe remains research gated in real arcane workbench",menu.getSlot(0).getItem().isEmpty(),"locked");ResearchProgress.add(fake.getPersistentData(),"Tiny Uranium");table.setChanged();int before=WandData.get(wand,Aspect.AIR);var tiny=menu.quickMoveStack(fake,0);check("native shapeless craft yields seven U235 piles for U238 andvis",tiny.is(EMTRecipes.item("ic2:small_uranium_235"))&&tiny.getCount()==7&&table.getItem(4).isEmpty()&&WandData.get(wand,Aspect.AIR)<before,tiny);menu.removed(fake);
  check("all18original IC2 explicit aspect registrations exist",data.getAsJsonArray("object_tags").size()==18&&TC4Addons.objectTag("ic2:rubber_sheet").getAmount(Aspect.AIR)==5&&TC4Addons.objectTag("ic2:macerator").getAmount(Aspect.MINE)==2,"18tags");var scanned=ScanTarget.item(item("ic2:electric_furnace"),l).aspects();check("real scanner uses original IC2 electric furnace aspects",scanned.getOrDefault("ignis",0)==3&&scanned.getOrDefault("metallum",0)==2&&scanned.getOrDefault("machina",0)==1,"scan"+scanned);
  var disabled=EMTRecipes.enabledResearches(data,Set.of("Thaumium Drill","Shield Focus"));check("disabled research cascades through original dependencies",!disabled.contains("Thaumium Drill")&&!disabled.contains("Drill of the Rockbreaker")&&!disabled.contains("Thaumium Omnitool")&&!disabled.contains("Shield Block")&&disabled.contains("Compressed Solars"),disabled.size());check("default config keeps all57researches and full disable removes all",EMTRecipes.enabledResearches(data,Set.of()).size()==57&&EMTRecipes.enabledResearches(data,data.getAsJsonArray("researches").asList().stream().map(r->r.getAsJsonObject().get("name").getAsString()).collect(java.util.stream.Collectors.toSet())).isEmpty(),"selection");
  for(String metal:List.of("iron","gold","copper","tin","silver","lead")){var out=ic2.api.recipe.Recipes.macerator.getOutputFor(item("tc4modern:"+metal+"_cluster"),false);check("native "+metal+" cluster produces22IC2small dust",out!=null&&out.items.getFirst().is(EMTRecipes.item("ic2:small_"+metal+"_dust"))&&out.items.getFirst().getCount()==22,out==null?"missing":out.items);}
  for(String metal:List.of("tin","silver","lead")){var smelting=new net.minecraft.world.item.crafting.SingleRecipeInput(item("tc4modern:"+metal+"_cluster"));var recipe=l.getRecipeManager().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.SMELTING,smelting,l);var result=recipe.map(r->r.value().assemble(smelting,l.registryAccess())).orElse(ItemStack.EMPTY);check("native "+metal+" clusters smelt to two compatible IC2 ingots",result.is(EMTRecipes.item("ic2:"+metal+"_ingot"))&&result.getCount()==2,result);}
  check("original optional-cluster aspects are native",AspectTable.get(item("tc4modern:tin_cluster")).getOrDefault("metallum",0)==5&&AspectTable.get(item("tc4modern:lead_cluster")).getOrDefault("ordo",0)==3,"metal5/order3");
  var pick=item("tc4modern:elemental_pickaxe");pick.enchant(l.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.FORTUNE),20);fake.setItemInHand(InteractionHand.MAIN_HAND,pick);fake.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);var orePos=base.offset(20,2,58);l.setBlock(orePos,net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(ResourceLocation.parse("ic2:tin_ore")).defaultBlockState(),3);fake.gameMode.destroyBlock(orePos);check("real native pick harvest converts IC2 tin ore into native cluster",l.getEntitiesOfClass(ItemEntity.class,new AABB(orePos).inflate(2)).stream().anyMatch(entity->entity.getItem().is(EMTRecipes.item("tc4modern:tin_cluster"))),"native drops");l.getEntitiesOfClass(ItemEntity.class,new AABB(orePos).inflate(2)).forEach(Entity::discard);
  var borePos=base.offset(26,2,58);l.setBlock(borePos.below(),ArcaneBore.BASE.get().defaultBlockState(),3);l.setBlock(borePos,ArcaneBore.BORE.get().defaultBlockState(),3);var bore=(ArcaneBore.BoreEntity)l.getBlockEntity(borePos);bore.setItem(0,item("tc4modern:focus_excavation"));bore.setItem(1,pick.copy());var target=borePos.above(4);field(bore,"fake",fake);field(bore,"dig",target);field(bore,"fortune",20);l.setBlock(target,net.minecraft.core.registries.BuiltInRegistries.BLOCK.get(ResourceLocation.parse("ic2:lead_ore")).defaultBlockState(),3);call(bore,"mine");check("real arcane bore uses same addon native cluster hook",l.isEmptyBlock(target)&&l.getEntitiesOfClass(ItemEntity.class,new AABB(borePos).inflate(3)).stream().anyMatch(entity->entity.getItem().is(EMTRecipes.item("tc4modern:lead_cluster"))),"bore");l.setBlock(borePos,Blocks.AIR.defaultBlockState(),3);l.setBlock(borePos.below(),Blocks.AIR.defaultBlockState(),3);fake.getInventory().clearContent();
 }
}
